DELETE FROM Person
WHERE id NOT IN (
  SELECT keep_id
  FROM (
    SELECT MIN(id) AS keep_id
    FROM Person
    GROUP BY email
  ) keepers
);

-- Alternative: ROW_NUMBER (choose the survivor via ORDER BY)
DELETE FROM Person
WHERE id IN (
  SELECT id
  FROM (
    SELECT id, ROW_NUMBER() OVER (PARTITION BY email ORDER BY id) AS rn
    FROM Person
  ) ranked
  WHERE rn > 1
);

-- MySQL / SQL Server: multi-table DELETE with a self join
-- (PostgreSQL: DELETE FROM Person p1 USING Person p2 WHERE p1.email = p2.email AND p1.id > p2.id)
DELETE p1
FROM Person p1
JOIN Person p2 ON p1.email = p2.email AND p1.id > p2.id;

-- Then stop new duplicates
ALTER TABLE Person ADD CONSTRAINT uq_person_email UNIQUE (email);

